-- E-commerce Store dataset (generated by scripts/build_datasets.py; do not edit by hand)
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS payments CASCADE;
DROP TABLE IF EXISTS order_items CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE users (
  user_id INTEGER PRIMARY KEY,
  username VARCHAR(40) NOT NULL UNIQUE,
  email VARCHAR(120) NOT NULL UNIQUE,
  full_name VARCHAR(80),
  country VARCHAR(40),
  signup_date DATE NOT NULL,
  is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
  deleted_at TIMESTAMP,
  CHECK (is_deleted OR deleted_at IS NULL)
);

CREATE TABLE categories (
  category_id INTEGER PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  parent_id INTEGER REFERENCES categories(category_id),
  CHECK (parent_id <> category_id)
);

CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  name VARCHAR(80) NOT NULL,
  category_id INTEGER NOT NULL REFERENCES categories(category_id),
  price NUMERIC(10,2) NOT NULL CHECK (price >= 0),
  stock INTEGER NOT NULL CHECK (stock >= 0),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATE NOT NULL
);

CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(user_id),
  order_date TIMESTAMP NOT NULL,
  status VARCHAR(12) NOT NULL CHECK (status IN ('pending','paid','shipped','delivered','cancelled','refunded')),
  shipping_country VARCHAR(40),
  coupon_code VARCHAR(20)
);

CREATE TABLE order_items (
  order_item_id INTEGER PRIMARY KEY,
  order_id INTEGER NOT NULL REFERENCES orders(order_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  unit_price NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0)
);

CREATE TABLE payments (
  payment_id INTEGER PRIMARY KEY,
  order_id INTEGER NOT NULL REFERENCES orders(order_id),
  amount NUMERIC(10,2) NOT NULL CHECK (amount >= 0),
  method VARCHAR(20) NOT NULL CHECK (method IN ('card','paypal','bank_transfer','gift_card')),
  status VARCHAR(10) NOT NULL CHECK (status IN ('success','failed','refunded')),
  paid_at TIMESTAMP NOT NULL
);

CREATE TABLE reviews (
  review_id INTEGER PRIMARY KEY,
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  user_id INTEGER NOT NULL REFERENCES users(user_id),
  rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title VARCHAR(100),
  body TEXT,
  created_at TIMESTAMP NOT NULL
);





















